import {
  TARGET_ROUTEROS,
  type GenerationMeta,
} from './types';
import { lines } from './utils';

export function generatedHeader(
  meta: GenerationMeta,
  title: string,
  notes: string[] = [],
): string {
  const rule = '# ' + '='.repeat(74);
  const body = [
    rule,
    `# ${title}`,
    `# Generated by MikroTik Toolkit v${meta.generatorVersion}`,
    `# Target: RouterOS ${TARGET_ROUTEROS} (tested on 7.24)`,
    `# Generated: ${meta.generatedAt}`,
    `# Configuration id: ${meta.configId}`,
    '#',
    '# This file is generated. Do not edit it by hand; change the form input',
    '# and regenerate. Re-importing replaces the objects tagged GEN-FW: or',
    '# GEN-BGP: from the previous run.',
    ...notes.map((note) => `# NOTE: ${note}`),
    rule,
  ];
  return lines(...body);
}

export function plainHeader(meta: GenerationMeta, title: string): string {
  return lines(
    `# ${title}`,
    `# Generated by MikroTik Toolkit v${meta.generatorVersion}`,
    `# Generated: ${meta.generatedAt}`,
    `# Configuration id: ${meta.configId}`,
  );
}
